"""核对 115% / 130% 两列的合并表。"""
import openpyxl

BASE = r'C:\Users\24380\Downloads\烧烤\兵哥烧烤菜单'
MERGED = r'C:\Users\24380\Documents\deepseek-harness\default-workspace\bingge\merged_out.xlsx'

wb = openpyxl.load_workbook(MERGED, data_only=True)
ws = wb['合并对照表']

print('表头:', [ws.cell(row=4, column=c).value for c in range(1, 12)])
rows = []
for r in range(5, ws.max_row + 1):
    if not isinstance(ws.cell(row=r, column=1).value, int):
        continue
    rows.append({
        'name': ws.cell(row=r, column=3).value,
        'b': ws.cell(row=r, column=4).value,
        'p115': ws.cell(row=r, column=5).value,
        'p130': ws.cell(row=r, column=6).value,
        'l': ws.cell(row=r, column=7).value,
        'd': ws.cell(row=r, column=9).value,
        'src': ws.cell(row=r, column=10).value,
    })
print('行数:', len(rows))

bad = []
for x in rows:
    if x['b'] is None:
        if x['p115'] not in (None, '') or x['p130'] not in (None, ''):
            bad.append(('林火序独有却有多倍值', x['name']))
        continue
    if x['p115'] in (None, '') or x['p130'] in (None, ''):
        bad.append(('缺值', x['name']))
        continue
    if abs(x['p115'] - x['b'] * 1.15) > 1e-6:
        bad.append(('115%算错', x['name'], x['b'], x['p115']))
    if abs(x['p130'] - x['b'] * 1.3) > 1e-6:
        bad.append(('130%算错', x['name'], x['b'], x['p130']))
print('115%/130% 校验:', 'OK' if not bad else bad)

n = sum(1 for x in rows if x['b'] is not None)
print('有倍数取值的行:', n)
print('样例:', [(x['name'], x['b'], round(x['p115'], 2), round(x['p130'], 2))
              for x in rows[:5] if x['b'] is not None])

for r in range(5, ws.max_row + 1):
    if ws.cell(row=r, column=1).value == '合计':
        print('合计行:', [ws.cell(row=r, column=c).value for c in range(1, 11)])

ws2 = wb['分类汇总']
print('汇总表头:', [ws2.cell(row=3, column=c).value for c in range(1, 10)])
for r in range(4, ws2.max_row + 1):
    vals = [ws2.cell(row=r, column=c).value for c in range(1, 10)]
    if vals[0]:
        print('汇总:', vals)
print('filter:', ws.auto_filter.ref, '| print:', ws.print_area)
print('说明页条目:', [wb['说明'].cell(row=r, column=1).value for r in range(3, 15)
                    if wb['说明'].cell(row=r, column=1).value])
