import io
import json
import sys
import urllib.parse
import urllib.request

sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding='utf-8')

UA = {'User-Agent': 'menu-image/1.0'}


def api(path, **params):
    url = 'https://world.openfoodfacts.org' + path + '?' + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers=UA)
    with urllib.request.urlopen(req, timeout=40) as r:
        return json.load(r)


try:
    d = api('/api/v2/search', search_terms="beck's beer", page_size=20,
            fields='code,product_name,quantity,brands,image_front_url,image_front_small_url')
    print('count', d.get('count'))
    for p in d.get('products', []):
        q = p.get('quantity') or ''
        print(' ', p.get('code'), '|', (p.get('product_name') or '')[:40], '|', q)
        if p.get('image_front_url'):
            print('    ', p['image_front_url'])
except Exception as e:
    print('ERR', type(e).__name__, str(e)[:120])
